def get_config_dir():
    """Folder tempat timer_config.json disimpan.

    PENTING: kalau di-build jadi .exe onefile (PyInstaller), __file__ dan
    sys.executable saat runtime menunjuk ke folder temp yang dibuat ULANG
    setiap kali exe dijalankan (mis. C:\\Users\\...\\AppData\\Local\\Temp\\_MEIxxxxx)
    lalu dihapus lagi begitu aplikasi ditutup. Kalau config disimpan di
    situ, jadinya seolah "ke-reset" tiap buka - apalagi kalau dijalankan
    otomatis dari shell:startup. Makanya untuk versi exe, config disimpan
    di folder permanen (%APPDATA%\\PopsnapTimer) yang sama dipakai terus
    setiap kali aplikasi dibuka, dari mana pun exe-nya dijalankan.
    """
    if getattr(sys, "frozen", False):
        base = os.environ.get("APPDATA") or os.path.expanduser("~")
        config_dir = os.path.join(base, "PopsnapTimer")
    else:
        config_dir = os.path.dirname(os.path.abspath(__file__))
    try:
        os.makedirs(config_dir, exist_ok=True)
    except Exception:
        pass
    return config_dir


